export interface PositionedSample {
    position: number;
    amount: number;
}

export interface SampleSummary {
    positions: number[];
    count: number;
    total: number;
    minimum: number | null;
    maximum: number | null;
}

export function summarizeSamples(
    samples: readonly PositionedSample[],
    fromPosition: number,
    toPosition: number
): SampleSummary {
    validatePosition(fromPosition);
    validatePosition(toPosition);
    if (fromPosition > toPosition) {
        throw new RangeError("fromPosition must not exceed toPosition");
    }

    const seen = new Set<number>();
    for (const sample of samples) {
        validatePosition(sample.position);
        if (!Number.isFinite(sample.amount)) {
            throw new RangeError("amount must be finite");
        }
        if (seen.has(sample.position)) {
            throw new TypeError("sample positions must be unique");
        }
        seen.add(sample.position);
    }

    const included = samples
        .filter((sample) => sample.position >= fromPosition && sample.position < toPosition)
        .slice()
        .sort((a, b) => a.position - b.position);
    const amounts = included.map((sample) => sample.amount);

    return {
        positions: included.map((sample) => sample.position),
        count: included.length,
        total: amounts.reduce((sum, amount) => sum + amount, 0),
        minimum: amounts.length === 0 ? null : Math.min(...amounts),
        maximum: amounts.length === 0 ? null : Math.max(...amounts)
    };
}

function validatePosition(position: number): void {
    if (!Number.isSafeInteger(position) || position < 0) {
        throw new RangeError("positions must be non-negative safe integers");
    }
}
```

