import { summarizeSamples } from "./solution";

function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

function throws(action: () => unknown, expected: typeof TypeError | typeof RangeError, message: string): void {
    let error: unknown;
    try { action(); } catch (caught) { error = caught; }
    assert(error instanceof expected, message);
}

const samples = Object.freeze([
    Object.freeze({ position: 5, amount: -2 }),
    Object.freeze({ position: 1, amount: 4 }),
    Object.freeze({ position: 3, amount: 1.5 }),
    Object.freeze({ position: 8, amount: 100 })
]);
const summary = summarizeSamples(samples, 1, 5);
assert(summary.positions.join(",") === "1,3,5", "range is inclusive and positions are numerically sorted");
assert(summary.count === 3, "count describes included samples");
assert(summary.total === 3.5, "total describes included samples");
assert(summary.minimum === -2 && summary.maximum === 4, "extrema describe included samples");
summary.positions[0] = 99;
assert(summarizeSamples(samples, 1, 5).positions.join(",") === "1,3,5", "positions array is fresh and isolated");

const singleton = summarizeSamples([{ position: 0, amount: 0 }], 0, 0);
assert(singleton.positions.join() === "0" && singleton.count === 1, "equal endpoints include their shared position");
assert(singleton.total === 0 && singleton.minimum === 0 && singleton.maximum === 0, "zero amount is summarized normally");

const emptyA = summarizeSamples(samples, 20, 30);
const emptyB = summarizeSamples(samples, 20, 30);
assert(emptyA.count === 0 && emptyA.total === 0, "empty result has zero count and total");
assert(emptyA.minimum === null && emptyA.maximum === null, "empty result has null extrema");
assert(emptyA.positions.length === 0 && emptyA.positions !== emptyB.positions, "empty positions arrays are fresh");

for (const invalidEndpoint of [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
    throws(() => summarizeSamples([], invalidEndpoint, 5), RangeError, "invalid fromPosition throws RangeError");
    throws(() => summarizeSamples([], 0, invalidEndpoint), RangeError, "invalid toPosition throws RangeError");
}
throws(() => summarizeSamples([], 5, 4), RangeError, "reversed endpoints throw RangeError");

for (const invalidPosition of [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
    throws(() => summarizeSamples([{ position: invalidPosition, amount: 1 }], 0, 0), RangeError, "every sample position is validated");
}
for (const invalidAmount of [NaN, Infinity, -Infinity, "1" as unknown as number]) {
    throws(() => summarizeSamples([{ position: 100, amount: invalidAmount }], 0, 0), RangeError, "amount outside requested range is still validated");
}
throws(() => summarizeSamples([{ position: 100, amount: 1 }, { position: 100, amount: 2 }], 0, 0), TypeError, "duplicate positions outside range throw TypeError");

assert(samples[0].position === 5 && samples[0].amount === -2, "input samples are not mutated");

